package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.lang.reflect.Field;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.utils.IOUtils;
import org.apache.commons.compress.utils.InflaterFactory;
import org.junit.*;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ZipArchiveInputStream_close_TriageGen0Test {

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    /**
     * Test to cover the case where close() is called when closed is false.
     * This covers the main logic: setting closed = true, calling in.close(), and inf.end().
     */
    @Test
    public void testClose_WhenNotClosed_Success() throws Exception {
        // We need to mock the underlying InputStream to verify close() is called
        InputStream mockIn = mock(InputStream.class);

        // ZipArchiveInputStream requires a valid ZIP header to initialize without immediate error in some versions,
        // but for testing the close() logic specifically, we can use reflection to inject mocks.
        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(new byte[0]));

        // Use reflection to inject the mocked InputStream and ensure we can control the state
        Field inField = ZipArchiveInputStream.class.getDeclaredField("in");
        inField.setAccessible(true);
        inField.set(zis, mockIn);

        // Access the 'closed' field via reflection to ensure it is false initially
        Field closedField = ZipArchiveInputStream.class.getDeclaredField("closed");
        closedField.setAccessible(true);
        closedField.set(zis, false);

        // To handle inf.end(), we need to ensure the Inflater is initialized or mock it if possible.
        // Since 'inf' is likely a java.util.zip.Inflater, we focus on the 'in.close()' call.

        zis.close();

        verify(mockIn, times(1)).close();
        boolean isClosed = (boolean) closedField.get(zis);
        assert(isClosed);
    }

    /**
     * Test to cover the branch where closed is already true.
     * The method should return immediately without calling in.close() again.
     */
    @Test
    public void testClose_WhenAlreadyClosed_DoesNothing() throws Exception {
        InputStream mockIn = mock(InputStream.class);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(new byte[0]));

        Field inField = ZipArchiveInputStream.class.getDeclaredField("in");
        inField.setAccessible(true);
        inField.set(zis, mockIn);

        Field closedField = ZipArchiveInputStream.class.getDeclaredField("closed");
        closedField.setAccessible(true);
        closedField.set(zis, true);

        zis.close();

        // Verify close was NOT called on the input stream because it was already closed
        verify(mockIn, never()).close();
    }

    /**
     * Test to cover the scenario where in.close() throws an IOException.
     */
    @Test
    public void testClose_WhenInCloseThrowsException() throws Exception {
        InputStream mockIn = mock(InputStream.class);
        doThrow(new IOException("Simulated IO error")).when(mockIn).close();

        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(new byte[0]));

        Field inField = ZipArchiveInputStream.class.getDeclaredField("in");
        inField.setAccessible(true);
        inField.set(zis, mockIn);

        Field closedField = ZipArchiveInputStream.class.getDeclaredField("closed");
        closedField.setAccessible(true);
        closedField.set(zis, false);

        thrown.expect(IOException.class);
        thrown.expectMessage("Simulated IO error");

        try {
            zis.close();
        } finally {
            // Even if close fails, the state might have been set to true depending on implementation
            // In the provided code, closed = true happens before in.close()
            boolean isClosed = (boolean) closedField.get(zis);
            assert(isClosed);
        }
    }
}
